begin;
-- Only structural definitions are imported; historical students, grades and signatures are excluded.
create table public.vertice_tcc_form_templates (
 code text primary key, version integer not null default 1, definition jsonb not null
);
alter table public.vertice_tcc_form_templates enable row level security;
create policy tcc_form_templates_read on public.vertice_tcc_form_templates for select to authenticated using(true);
revoke all on public.vertice_tcc_form_templates from public,anon,authenticated;
grant select on public.vertice_tcc_form_templates to authenticated;
