insert into public.vertice_tcc_form_templates(code,definition) values ('ata','{"label": "Ata de apresentação e defesa", "source": "CCG-FOR-24", "role_group": "examiner", "note": "Notas transcritas para a minuta. A emissão não lança notas no histórico e não altera a etapa acadêmica.", "fields": [{"key": "title", "label": "Título do trabalho", "type": "text", "required": true, "readonly": true}, {"key": "authors", "label": "Autores e matrículas", "type": "textarea", "required": false}, {"key": "advisor", "label": "Orientador(a)", "type": "text", "required": false}, {"key": "coadvisor", "label": "Coorientador(a)", "type": "text", "required": false}, {"key": "semester", "label": "Semestre", "type": "text", "required": true}, {"key": "class", "label": "Turma / período", "type": "text", "required": false}, {"key": "city", "label": "Local de emissão", "type": "text", "required": true}, {"key": "date", "label": "Data de emissão", "type": "date", "required": true}, {"key": "responsible", "label": "Responsável pelo preenchimento", "type": "text", "required": true}, {"key": "previous_protocol", "label": "Protocolo de emissão anterior (se houver)", "type": "text", "required": false}, {"key": "event_date", "label": "Data da defesa", "type": "date", "required": true}, {"key": "event_time", "label": "Horário", "type": "text", "required": true}, {"key": "location", "label": "Local / modalidade", "type": "text", "required": true}, {"key": "examiner1", "label": "Avaliador 1", "type": "text", "required": true}, {"key": "grade1", "label": "Nota do avaliador 1", "type": "number", "required": true, "min": 0, "max": 10}, {"key": "examiner2", "label": "Avaliador 2", "type": "text", "required": false}, {"key": "grade2", "label": "Nota do avaliador 2", "type": "number", "required": false, "min": 0, "max": 10}, {"key": "examiner3", "label": "Avaliador 3", "type": "text", "required": false}, {"key": "grade3", "label": "Nota do avaliador 3", "type": "number", "required": false, "min": 0, "max":