insert into public.vertice_tcc_form_templates(code,definition) values ('publicacao','{"label": "Termo de autorização de publicação", "source": "CCG-MDL-24", "role_group": "work", "note": "Registro documental da manifestação. Não torna o acervo público nem substitui a assinatura dos titulares.", "fields": [{"key": "title", "label": "Título do trabalho", "type": "text", "required": true, "readonly": true}, {"key": "authors", "label": "Autores e matrículas", "type": "textarea", "required": false}, {"key": "advisor", "label": "Orientador(a)", "type": "text", "required": false}, {"key": "coadvisor", "label": "Coorientador(a)", "type": "text", "required": false}, {"key": "semester", "label": "Semestre", "type": "text", "required": true}, {"key": "class", "label": "Turma / período", "type": "text", "required": false}, {"key": "city", "label": "Local de emissão", "type": "text", "required": true}, {"key": "date", "label": "Data de emissão", "type": "date", "required": true}, {"key": "responsible", "label": "Responsável pelo preenchimento", "type": "text", "required": true}, {"key": "previous_protocol", "label": "Protocolo de emissão anterior (se houver)", "type": "text", "required": false}, {"key": "material", "label": "Natureza do material", "type": "text", "required": true}, {"key": "declarants", "label": "Autores titulares e responsáveis pela manifestação", "type": "textarea", "required": true}, {"key": "repository", "label": "Repositório e instituição destinatária", "type": "text", "required": true}, {"key": "permission", "label": "Manifestação de publicação", "type": "select", "required": true, "options": ["Autoriza nas condições descritas", "Não autoriza", "Autoriza após embargo"]}, {"key": "scope", "label": "Condições, finalidades e modalidades de acesso", "type": "textarea", "required": true}, {"key": "embargo", "label": "Prazo / data e condições de embargo", "type": "text", "required": false}, {"key": "email_permission", "label": "Divulgação de e-mail", "type": "se