insert into public.vertice_tcc_form_templates(code,definition) values ('imagem','{"label": "Termo de uso de imagem", "source": "Permissão de uso de imagem", "role_group": "work", "note": "A emissão da minuta não concede consentimento por terceiros nem publica imagens.", "fields": [{"key": "title", "label": "Título do trabalho", "type": "text", "required": true, "readonly": true}, {"key": "authors", "label": "Autores e matrículas", "type": "textarea", "required": false}, {"key": "advisor", "label": "Orientador(a)", "type": "text", "required": false}, {"key": "coadvisor", "label": "Coorientador(a)", "type": "text", "required": false}, {"key": "semester", "label": "Semestre", "type": "text", "required": true}, {"key": "class", "label": "Turma / período", "type": "text", "required": false}, {"key": "city", "label": "Local de emissão", "type": "text", "required": true}, {"key": "date", "label": "Data de emissão", "type": "date", "required": true}, {"key": "responsible", "label": "Responsável pelo preenchimento", "type": "text", "required": true}, {"key": "previous_protocol", "label": "Protocolo de emissão anterior (se houver)", "type": "text", "required": false}, {"key": "declarants", "label": "Pessoas que deverão manifestar o consentimento", "type": "textarea", "required": true}, {"key": "permission", "label": "Manifestação de uso de imagem", "type": "select", "required": true, "options": ["Autoriza nas condições descritas", "Não autoriza"]}, {"key": "purpose", "label": "Finalidade específica e contexto das imagens", "type": "textarea", "required": true}, {"key": "scope", "label": "Meios de utilização, prazo e limites", "type": "textarea", "required": true}, {"key": "revocation", "label": "Canal e condições para solicitar revogação", "type": "textarea", "required": true}, {"key": "signatories", "label": "Titulares e responsáveis que deverão assinar", "type": "textarea", "required": true}]}'::jsonb);
insert into public.vertice_tcc_form_templates(code,definition) values ('final','{"label": "Roteiro e registro da versão final — TCC II", "source": "Modelo TCC II", "role_group": "work", "note": "Roteiro de conteúdo e registro de entrega. O manuscrito original deve ser anexado; a emissão não certifica conformidade integral com normas de formatação.", "fields": [{"key": "title", "label": "Título do trabalho", "type": "text", "required": true, "readonly": true}, {"key": "authors", "label": "Autores e matrículas", "type": "textarea", "required": false}, {"key": "advisor", "label": "Orientador(a)", "type": "text", "required": false}, {"key": "coadvisor", "label": "Coorientador(a)", "type": "text", "required": false}, {"key": "semester", "label": "Semestre", "type": "text", "required": true}, {"key": "class", "label": "Turma / período", "type": "text", "required": false}, {"key": "city", "label": "Local de emissão", "type": "text", "required": true}, {"key": "date", "label": "Data de emissão", "type": "date", "required": true}, {"key": "responsible", "label": "Responsável pelo preenchimento", "type": "text", "required": true}, {"key": "previous_protocol", "label": "Protocolo de emissão anterior (se houver)", "type": "text", "required": false}, {"key": "abstract", "label": "Resumo", "type": "textarea", "required": true}, {"key": "keywords", "label": "Palavras-chave", "type": "text", "required": true}, {"key": "abstract_foreign", "label": "Resumo em língua estrangeira", "type": "textarea", "required": false}, {"key": "introduction", "label": "Introdução", "type": "textarea", "required": true}, {"key": "development", "label": "Desenvolvimento / capítulos e resultados", "type": "textarea", "required": true}, {"key": "conclusions", "label": "Considerações finais", "type": "textarea", "required": true}, {"key": "references", "label": "Referências", "type": "textarea", "required": true}, {"key": "format_rules", "label": "Orientações de formatação adotadas pela IES", "type": "tex