insert into public.vertice_tcc_form_templates(code,definition) values ('dossie','{"label": "Dossiê documental de TCC", "source": "Conjunto de formulários TCC I / TCC II", "role_group": "work", "note": "Dossiê de evidências do percurso. Não substitui aprovação, assinatura, depósito ou autorização de publicação.", "fields": [{"key": "title", "label": "Título do trabalho", "type": "text", "required": true, "readonly": true}, {"key": "authors", "label": "Autores e matrículas", "type": "textarea", "required": false}, {"key": "advisor", "label": "Orientador(a)", "type": "text", "required": false}, {"key": "coadvisor", "label": "Coorientador(a)", "type": "text", "required": false}, {"key": "semester", "label": "Semestre", "type": "text", "required": true}, {"key": "class", "label": "Turma / período", "type": "text", "required": false}, {"key": "city", "label": "Local de emissão", "type": "text", "required": true}, {"key": "date", "label": "Data de emissão", "type": "date", "required": true}, {"key": "responsible", "label": "Responsável pelo preenchimento", "type": "text", "required": true}, {"key": "previous_protocol", "label": "Protocolo de emissão anterior (se houver)", "type": "text", "required": false}, {"key": "phase", "label": "Etapa coberta", "type": "select", "required": true, "options": ["TCC I", "TCC II", "TCC I e II"]}, {"key": "document_inventory", "label": "Relação de documentos e versões", "type": "textarea", "required": true}, {"key": "orientation_summary", "label": "Síntese do acompanhamento", "type": "textarea", "required": true}, {"key": "assessment_summary", "label": "Qualificação, defesa e resultados registrados", "type": "textarea", "required": true}, {"key": "pending", "label": "Pendências e providências", "type": "textarea", "required": true}, {"key": "destination", "label": "Finalidade e destinatário institucional", "type": "textarea", "required": true}]}'::jsonb);
insert into public.vertice_tcc_form_templates(code,definition) values ('edital','{"label": "Edital de TCC e programação de defesas", "source": "Editais de TCC e modelo institucional", "role_group": "manager", "note": "Minuta vinculada ao trabalho de referência. A coordenação deve revisar o escopo, o calendário e os critérios da instituição antes da assinatura.", "fields": [{"key": "title", "label": "Título do trabalho", "type": "text", "required": true, "readonly": true}, {"key": "authors", "label": "Autores e matrículas", "type": "textarea", "required": false}, {"key": "advisor", "label": "Orientador(a)", "type": "text", "required": false}, {"key": "coadvisor", "label": "Coorientador(a)", "type": "text", "required": false}, {"key": "semester", "label": "Semestre", "type": "text", "required": true}, {"key": "class", "label": "Turma / período", "type": "text", "required": false}, {"key": "city", "label": "Local de emissão", "type": "text", "required": true}, {"key": "date", "label": "Data de emissão", "type": "date", "required": true}, {"key": "responsible", "label": "Responsável pelo preenchimento", "type": "text", "required": true}, {"key": "previous_protocol", "label": "Protocolo de emissão anterior (se houver)", "type": "text", "required": false}, {"key": "notice_title", "label": "Título do edital / comunicado", "type": "text", "required": true}, {"key": "notice_number", "label": "Número e versão", "type": "text", "required": true}, {"key": "scope", "label": "Escopo: curso, turmas e semestre", "type": "textarea", "required": true}, {"key": "procedures", "label": "Procedimentos e documentos de submissão", "type": "textarea", "required": true}, {"key": "deadlines", "label": "Prazos e canais institucionais", "type": "textarea", "required": true}, {"key": "schedule", "label": "Programação das defesas: trabalho, autores, data, horário e local", "type": "textarea", "required": true}, {"key": "evaluation_rules", "label": "Critérios de avaliação e regulamento adotado", "type": "textarea", "required": true}, {"key": "signatories", "label": "Autoridade responsável pela aprovação e assinatura", "type": "textarea", "required": true}]}'::jsonb);
insert into public.vertice_doc_categories(code,label,tier,linked_module,linked_tab,sort_order)
values ('TCC_FORM','TCC - Modelos e documentos','superior','ACAD_TCC','tcc',111),
       ('TCC_ANEXO','TCC - Originais e comprovantes','superior','ACAD_TCC','tcc',112)
on conflict(code) do nothing;
create table public.vertice_tcc_forms (
 id uuid primary key, institution_id uuid not null references public.vertice_institutions(id),
 work_id uuid not null references public.vertice_tcc_works(id),
 course_id uuid not null references public.vertice_courses(id),
 template text not null references public.vertice_tcc_form_templates(code), template_version integer not null default 1,
 answers jsonb not null default '{}' check(jsonb_typeof(answers)='object'),
 attachments jsonb not null default '[]' check(jsonb_typeof(attachments)='array'),
 revision integer not null default 1, owner_id uuid not null references auth.users(id), updated_by uuid not null references auth.users(id),
 status text not null default 'rascunho' check(status in ('rascunho','gerado')),
 document_id uuid references public.vertice_documents(id), repository_file_id uuid references public.vertice_repository_files(id),
 repository_request_id uuid not null references public.vertice_repository_requests(id),
 completed_by uuid references auth.users(id),completed_at timestamptz,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check(status<>'gerado' or (document_id is not null and repository_file_id is not null and completed_by is not null and completed_at is not null))
);
alter table public.vertice_tcc_forms enable row level security;
create index tcc_forms_institution_idx on public.vertice_tcc_forms(institution_id);
create index tcc_forms_work_idx on public.vertice_tcc_forms(work_id);
create policy tcc_forms_read on public.vertice_tcc_forms for select to authenticated using(vertice_private.can_read_institution(institution_id));
revoke all on public.vertice_tcc_forms from public,anon,authenticated;
grant select on public.vertice_tcc_forms to authenticated;

create function vertice_private.tcc_form_write(p_id uuid,p_institution uuid,p_work uuid,p_template text,p_answers jsonb,p_attachments jsonb,p_revision integer,p_pdf jsonb default null)
returns public.vertice_tcc_forms language plpgsql security definer set search_path='' as $$
declare
 f public.vertice_tcc_forms; w public.vertice_tcc_works; def jsonb; field jsonb; a jsonb; k text; v text;
 doc uuid; annexdoc uuid; request_id uuid; repository_file uuid; size_total bigint:=0;
 path_prefix text; course_name text; user_mail text; actor_roles text[]; manager boolean; role_group text;
begin
 if p_revision is null or p_revision<0 then raise exception 'Revisão inválida.'; end if;
 if auth.uid() is null or not coalesce(vertice_private.can_read_institution(p_institution),false)
 or not coalesce(vertice_private.has_role(p_institution,array['gestor','equipe']),false) then
  raise exception 'Edição não autorizada. Verifique a instituição, o papel e a autenticação de dois fatores.' using errcode='42501';
 end if;
 select * into w from public.vertice_tcc_works where id=p_work and institution_id=p_institution;
 if not found then raise exception 'Trabalho de TCC não encontrado nesta instituição.' using errcode='42501'; end if;
 select definition into def from public.vertice_tcc_form_templates where code=p_template;
 if def is null then raise exception 'Modelo inválido.'; end if;
 manager:=vertice_private.has_role(p_institution,array['gestor']);
 select lower(email) into user_mail from auth.users where id=auth.uid();
 select array_agg(p.role) into actor_roles from public.vertice_tcc_participants p
 where p.work_id=p_work and p.institution_id=p_institution and p.valid_until is null and lower(p.person_email)=user_mail;
 role_group:=def->>'role_group';
 if not manager then
  if role_group='manager' or
   (role_group='advisor' and not coalesce(actor_roles&&array['advisor','coadvisor','discipline_teacher'],false)) or
   (role_group='examiner' and not coalesce(actor_roles&&array['examiner','reviewer','discipline_teacher'],false)) or
   (role_group='work' and not (coalesce(w.created_by=auth.uid(),false) or coalesce(actor_roles&&array['author','advisor','coadvisor','discipline_teacher','examiner','reviewer'],false))) then
   raise exception 'Seu vínculo no TCC não permite emitir este modelo. Solicite à coordenação o vínculo adequado.' using errcode='42501';
  end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into f from public.vertice_tcc_forms where id=p_id for update;
 if found then
  if f.institution_id<>p_institution or f.work_id<>p_work or (f.owner_id<>auth.uid() and not manager) then
   raise exception 'Somente o responsável ou gestor pode editar; o trabalho não pode ser substituído.' using errcode='42501';
  end if;
  if f.status='gerado' then
   if p_pdf is not null then return f; end if;
   raise exception 'Documento gerado e preservado. Crie outro formulário para uma nova emissão.';
  end if;
  if f.revision<>p_revision then raise exception 'O formulário mudou em outra sessão. Recarregue antes de salvar.' using errcode='40001'; end if;
 elsif p_revision<>0 or p_pdf is not null then raise exception 'Salve o rascunho antes de emitir.';
 end if;
 if p_answers is null or jsonb_typeof(p_answers)<>'object' or p_attachments is null or jsonb_typeof(p_attachments)<>'array'
 or jsonb_array_length(p_attachments)>20 or octet_length(p_answers::text)>250000 then raise exception 'Formulário inválido ou acima do limite.'; end if;
 for k in select jsonb_object_keys(p_answers) loop
  if jsonb_typeof(p_answers->k)<>'string' then raise exception 'Os campos devem conter texto.'; end if;
 end loop;
 -- Never trust a browser-supplied title or course; retain only fields for this template.
 p_answers:=(select coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb) from jsonb_each(p_answers) e
 where exists(select 1 from jsonb_array_elements(def->'fields') ft(item) where ft.item->>'key'=e.key));
 p_answers:=p_answers||jsonb_build_object('title',w.title);
 select name into course_name from public.vertice_courses where id=w.course_id and institution_id=p_institution;
 if course_name is null then raise exception 'Curso do trabalho não pertence à instituição.'; end if;
 path_prefix:=p_institution::text||'/tcc/'||p_id::text||'/';
 for a in select value from jsonb_array_elements(p_attachments) loop
  if coalesce(a->>'path','') not like path_prefix||'%' or (a->>'path') like '%..%'
   or coalesce(a->>'mime','') not in ('application/pdf','image/png','image/jpeg')
   or coalesce(a->>'sha256','') !~ '^[0-9a-f]{64}$'
   or coalesce(a->>'size','') !~ '^[0-9]+$' then raise exception 'Anexo inválido.'; end if;
  if (a->>'size')::bigint not between 1 and 5242880 or not exists(
   select 1 from storage.objects o where o.bucket_id='vertice-documents' and o.name=a->>'path'
    and (o.metadata->>'size')::bigint=(a->>'size')::bigint
  ) then raise exception 'Anexo não encontrado ou tamanho divergente.'; end if;
  size_total:=size_total+(a->>'size')::bigint;
 end loop;
 if size_total>20971520 then raise exception 'Os anexos devem somar no máximo 20 MB.'; end if;
 for field in select value from jsonb_array_elements(def->'fields') loop
  k:=field->>'key';v:=trim(coalesce(p_answers->>k,''));
  if v<>'' and field->>'type'='number' then
   if v !~ '^[0-9]+(\.[0-9]+)?$' or length(v)>12 then raise exception 'Nota inválida: %.',field->>'label'; end if;
   if (v::numeric)<(field->>'min')::numeric or (v::numeric)>(field->>'max')::numeric then raise exception 'Nota fora do intervalo: %.',field->>'label'; end if;
  end if;
  if v<>'' and field ? 'options' and not exists(select 1 from jsonb_array_elements_text(field->'options') op(choice) where op.choice=v) then raise exception 'Opção inválida: %.',field->>'label'; end if;
  if p_pdf is not null and coalesce((field->>'required')::boolean,false) and v='' then raise exception 'Campo obrigatório: %.',field->>'label'; end if;
  if p_pdf is not null and v<>'' and field->>'type'='date' then perform v::date; end if;
 end loop;
 if p_pdf is not null then
  if f.answers<>p_answers or f.attachments<>p_attachments or f.template<>p_template then raise exception 'Salve as alterações antes de gerar o PDF.'; end if;
  if p_answers->>'semester' !~ '^[0-9]{4}[-/][12]$' then raise exception 'Use o semestre no formato AAAA/1 ou AAAA/2.'; end if;
  if p_template in ('final','dossie') and jsonb_array_length(p_attachments)=0 then raise exception 'Anexe o manuscrito ou documento original.'; end if;
  if p_template='ata' then
   foreach k in array array['2','3'] loop
    if (trim(coalesce(p_answers->>('examiner'||k),''))='')<>(trim(coalesce(p_answers->>('grade'||k),''))='') then raise exception 'Preencha nome e nota do avaliador % ou deixe ambos vazios.',k; end if;
   end loop;
  end if;
  if p_answers->>'permission'='Autoriza após embargo' and length(trim(coalesce(p_answers->>'embargo','')))=0 then raise exception 'Informe as condições do embargo.'; end if;
  if coalesce(p_pdf->>'path','') not like path_prefix||'%' or (p_pdf->>'path') like '%..%'
   or coalesce(p_pdf->>'sha256','') !~ '^[0-9a-f]{64}$' or coalesce(p_pdf->>'size','') !~ '^[0-9]+$' then raise exception 'PDF inválido.'; end if;
  if (p_pdf->>'size')::bigint not between 1 and 31457280 or not exists(
   select 1 from storage.objects o where o.bucket_id='vertice-documents' and o.name=p_pdf->>'path'
    and (o.metadata->>'size')::bigint=(p_pdf->>'size')::bigint and o.metadata->>'mimetype'='application/pdf'
  ) then raise exception 'PDF não localizado no armazenamento.'; end if;
  repository_file:=(p_pdf->>'repository_file_id')::uuid;
  request_id:=f.repository_request_id;
  if repository_file is null or coalesce(p_pdf->>'repository_path','')<>p_institution::text||'/'||request_id::text||'/'||repository_file::text||'.pdf' or not exists(
   select 1 from storage.objects o where o.bucket_id='vertice-repositorios' and o.name=p_pdf->>'repository_path'
    and o.owner_id=auth.uid()::text and (o.metadata->>'size')::bigint=(p_pdf->>'size')::bigint and o.metadata->>'mimetype'='application/pdf'
  ) then raise exception 'PDF não localizado no repositório da Mesa Digital.'; end if;
  insert into public.vertice_repository_files(id,institution_id,request_id,storage_path,file_name,size_bytes,mime_type,uploaded_by,status,document_category,upload_note)
  values(repository_file,p_institution,request_id,p_pdf->>'repository_path','tcc-'||p_id||'.pdf',(p_pdf->>'size')::bigint,'application/pdf',auth.uid(),'enviado','nao_classificado',
   'Modelo '||p_template||' | Protocolo '||p_id||' | SHA-256 '||(p_pdf->>'sha256')||' | Minuta; assinatura e validação pendentes.');
  insert into public.vertice_documents(institution_id,category_code,title,description,storage_path,file_name,file_size,mime_type,sha256,course_id,tags,linked_module,linked_entity_type,linked_entity_id,uploaded_by,ai_status)
  values(p_institution,'TCC_FORM',left((def->>'label')||' - '||w.title,500),
   'TCC / '||course_name||' | Protocolo '||p_id||' | Revisão '||f.revision||' | Minuta: assinatura não verificada.',
   p_pdf->>'path','tcc-'||p_id||'.pdf',(p_pdf->>'size')::bigint,'application/pdf',p_pdf->>'sha256',w.course_id,
   array['TCC',p_template,p_answers->>'semester'],'ACAD_TCC','tcc_work',p_work,auth.uid(),'pending') returning id into doc;
  for a in select value from jsonb_array_elements(p_attachments) loop
   insert into public.vertice_documents(institution_id,category_code,title,description,storage_path,file_name,file_size,mime_type,sha256,course_id,linked_module,linked_entity_type,linked_entity_id,uploaded_by,ai_status)
   values(p_institution,'TCC_ANEXO',a->>'name','Original de anexo | Protocolo '||p_id||' | '||(a->>'kind'),a->>'path',a->>'name',(a->>'size')::bigint,a->>'mime',a->>'sha256',w.course_id,'ACAD_TCC','tcc_work',p_work,auth.uid(),'pending') returning id into annexdoc;
  end loop;
  -- Administrative evidence only: never approve a work, post a grade, credit hours,
  -- register consent for another person, or change repository visibility here.
  update public.vertice_tcc_forms set status='gerado',document_id=doc,repository_file_id=repository_file,
   completed_by=auth.uid(),completed_at=now(),updated_at=now(),updated_by=auth.uid() where id=p_id returning * into f;
 else
  if f.id is null then
   insert into public.vertice_repository_requests(institution_id,course_id,title,document_code,semester,instructions,assigned_to,created_by,repository_section)
   values(p_institution,w.course_id,left('TCC - '||(def->>'label')||' - '||w.title,500),'TCC-FORM',
    case when p_answers->>'semester' ~ '^[0-9]{4}[-/][12]$' then p_answers->>'semester' else null end,
    'Conferir identidade, conteúdo, assinatura e indicadores aplicáveis; minuta gerada não equivale a documento assinado.',auth.uid(),auth.uid(),'nao_classificado') returning id into request_id;
   insert into public.vertice_tcc_forms(id,institution_id,work_id,course_id,template,answers,attachments,owner_id,updated_by,repository_request_id)
   values(p_id,p_institution,p_work,w.course_id,p_template,p_answers,p_attachments,auth.uid(),auth.uid(),request_id) returning * into f;
  else
   update public.vertice_tcc_forms set template=p_template,answers=p_answers,attachments=p_attachments,revision=revision+1,updated_at=now(),updated_by=auth.uid() where id=p_id returning * into f;
  end if;
  update public.vertice_repository_requests set title=left('TCC - '||(def->>'label')||' - '||w.title,500),
   semester=case when p_answers->>'semester' ~ '^[0-9]{4}[-/][12]$' then p_answers->>'semester' else null end
  where id=f.repository_request_id;
 end if;
 return f;
end $$;
revoke all on function vertice_private.tcc_form_write(uuid,uuid,uuid,text,jsonb,jsonb,integer,jsonb) from public,anon;
grant execute on function vertice_private.tcc_form_write(uuid,uuid,uuid,text,jsonb,jsonb,integer,jsonb) to authenticated;
create function public.vertice_tcc_form_save(p_id uuid,p_institution uuid,p_work uuid,p_template text,p_answers jsonb,p_attachments jsonb,p_revision integer,p_pdf jsonb default null)
returns public.vertice_tcc_forms language sql security invoker set search_path='' as $$
 select vertice_private.tcc_form_write(p_id,p_institution,p_work,p_template,p_answers,p_attachments,p_revision,p_pdf);
$$;
revoke all on function public.vertice_tcc_form_save(uuid,uuid,uuid,text,jsonb,jsonb,integer,jsonb) from public,anon;
grant execute on function public.vertice_tcc_form_save(uuid,uuid,uuid,text,jsonb,jsonb,integer,jsonb) to authenticated;
commit;
